def get_all_pages():
    pages = []
    url   = f"https://api.notion.com/v1/databases/{PLAN_DB}/query"
    body  = {
        "sorts": [{"property": "학습날짜", "direction": "ascending"}],
        "page_size": 100
    }
    while True:
        res  = requests.post(url, headers=HEADERS, json=body)
        data = res.json()
        pages.extend(data.get("results", []))
        if not data.get("has_more"):
            break
        body["start_cursor"] = data["next_cursor"]
    return pages

def update_page(page_id, 일차, 단계, 공부범위, 교재페이지, 오늘할일, 학습목표):
    url  = f"https://api.notion.com/v1/pages/{page_id}"
    body = {
        "properties": {
            "학습목표":  {"title":     [{"text": {"content": 학습목표}}]},
            "단계":      {"select":    {"name": 단계}},
            "공부범위":  {"rich_text": [{"text": {"content": 공부범위}}]},
            "교재페이지":{"rich_text": [{"text": {"content": 교재페이지}}]},
            "오늘할일":  {"rich_text": [{"text": {"content": 오늘할일}}]},
            "상태":      {"select":    {"name": "예정"}},
        }
    }
    res = requests.patch(url, headers=HEADERS, json=body)
    if res.status_code == 200:
        print(f"  ✅ {일차:>3}일차 [{단계}] {공부범위}")
    else:
        print(f"  ❌ {일차}일차 오류: {res.json().get('message','')}")

if __name__ == "__main__":
    print("=" * 60)
    print("📅 학습 계획 DB 업데이트 시작! (학습목표 포함)")
    print("=" * 60)

    print("\n① 기존 페이지 불러오는 중...")
    pages = get_all_pages()
    print(f"  총 {len(pages)}개 페이지 로드 완료")

    print("\n② 내용 업데이트 중...")
    for i, page in enumerate(pages):
        if i >= len(SCHEDULE):
            break
        일차, 단계, 공부범위, 교재페이지, 오늘할일, 학습목표 = SCHEDULE[i]
        update_page(page["id"], 일차, 단계, 공부범위, 교재페이지, 오늘할일, 학습목표)

    print("\n" + "=" * 60)
    print(f"🎉 총 {min(len(pages), len(SCHEDULE))}개 업데이트 완료!")
    print("=" * 60)